j:jelly.g:evaluate:
	var is_doctype = jelly.jvar_cxs_doctype;
	var index = jelly.jvar_cxs_index;
	var docIdArray = jelly.jvar_cxs_result.id.split(":");
	var recordId = docIdArray[1];
	var title = jelly.jvar_cxs_result.title;
    title = GlideStringUtil.escapeHTML(title);
	var snippet = jelly.jvar_cxs_result.snippet;
	var itemLink = jelly.jvar_cxs_result.link + "${AMP}sysparm_stack=no${AMP}sysparm_context=popup${AMP}sysparm_no_create=true${AMP}sysparm_no_update=true${AMP}sysparm_no_info=true${AMP}sysparm_no_history=true${AMP}sysparm_no_suggest=true${AMP}sysparm_no_create_incident=true${AMP}sysparm_no_rating=true";
	var author = jelly.jvar_cxs_result.meta.author;

	var articleViews = jelly.jvar_cxs_result.meta.viewCount;
	var answerCount = jelly.jvar_cxs_result.meta.answerCount;
	var voteCount = jelly.jvar_cxs_result.meta.votes;

	var articleCreatedDate = '';
	var questionGr = new GlideRecord('kb_social_qa_question');
	questionGr.addActiveQuery();
	if(questionGr.get(recordId))
		articleCreatedDate = questionGr.getValue('sys_created_on');

	var gdt = new GlideDateTime();
	if(articleCreatedDate) {
		gdt.setDisplayValue(articleCreatedDate);
		articleCreatedDate = gdt.getDate().getDisplayValue();
	}


	var result_action_label = jelly.jvar_cxs_action_label;
	var result_action_value = jelly.jvar_cxs_action_value;

	var catArray = jelly.jvar_cxs_result.meta.parentCategories.reverse();
	var categoryBreadCrumb = "";
	if(new global.GlobalKnowledgeUtil().getDirection() == "ltr")
		categoryBreadCrumb = catArray.join(" / ");
	else
		categoryBreadCrumb = catArray.join(" \ ");

	categoryBreadCrumb = GlideStringUtil.escapeHTML(categoryBreadCrumb);

	var show = {
		"author": (gs.getProperty("glide.knowman.search.show_author", "true") == "true" ? true : false),
		"category" : (gs.getProperty("glide.knowman.search.show_category", "true") == "true" ? true: false),
		"views": (gs.getProperty('glide.knowman.search.show_view_count', "true") == "true" ? true: false),
		"lastModified": (gs.getProperty("glide.knowman.search.show_last_modified", "true") == "true" ? true : false)
	}
	var ariaGridCell = "gridcell";
	var ariaGroup = 'group';
	var ariaPresentation = "presentation";
